window.POETRY_REGISTER("v5-extra-11-12-0-6a95d53306e6.js",{"poems":[[47464,2],[49184,2],[49185,2],[52066,2],[52349,2],[52651,2],[53068,2],[55491,2],[57946,2],[191197,7],[272102,7],[288143,7],[288883,7],[289440,7],[306892,7],[345996,9],[375306,10],[420547,8],[442436,8],[556446,8],[650074,5],[670944,5],[682077,5],[725696,5],[744061,21]],"pairs":[["如今五里十里野火烧茫茫","君不见西施绿珠颜色可倾国",0],["蕴奇谋广智者为盗国之贼","曾未若轩后顺风兮清静自化",1],["君不见贾太傅忌鵩而愁吟","君不见四皓避秦峨峨恋商岭",2],["或民族文化交流的研究上","都有着不可忽视的宝贵价值",3],["是谅先于长庆四年守苏州","至此时相距七年而移守桂州",4],["称其从叔高祖元进所手录","黄之隽邵泰储大文皆为之序",5],["显为诗人重游九华山之作","所谓昔年乃距重游时六七年",6],["修鳞之喜横海兮纷潾漩沿","游神于六合之外兮希夷自然",7],["至多可能只有赵志诗三首","甚或此诗集只是赵志抄录者",8],["此时有宗古先生仁义礼信","根于心而能以此心确然履践",9],["盖欲天下知将帅未尝无人","夫岂必弧矢之弃而笔砚之亲",10],["咎将谁执兮岂天赋之未薖","落日下大墅兮慨高风之吟哦",11],["一琴一剑一童一鹤一茶瓯","自不须苦苦高卧元龙百尺楼",12],["或神丁从驾兮车骑之辚辚","冬寒春暖兮湖草几番之青青",13],["水潦和尚不合吃马师一踏","天下大禅佛枉自吃了四藤条",14],["维子之乐兮固放情于丘壑","逢时之清兮胡不徼世之名誉",15],["我马饱粟兮彼食不詜秕糠","我麦满舟兮彼无以送其死亡",16],["山川摇落兮老冉冉而怀土","歌匡山兮将归望孤云于极浦",17],["又奚慕乎夷齐采薇于首阳","赋归来兮彭泽怀高士于南昌",17],["岁冉冉其逾迈兮曷云能来","回念昔者之欢会兮今焉别离",18],["不觉为之嗟咨叹泣而涕洟","嗟石何不居乎治世育乎德门",19],["到西伯方才发了个大粗芽","可恨那说舌头的杀才崇侯虎",20],["到后来楚汉争锋换了世界","那刘邦是一个龙胎自然不糙",20],["且莫说关张义气卧龙的品","就是那风流常山是何等英豪",20],["你拖着杆长枪赋的什么诗","倒惹得一把火燎光了胡子嘴",20],["这不是从前说的个铁板数","就象那打骰子的凑巧拼了烘",20],["不多时把个刀把给了刘聪","只见他油锅里的螃蟹支不住",20],["大翻案白版登舟蛇做了龙","次后来糊里糊涂又挨了几日",20],["头一个是齐来第二个是梁","姓萧的他一笔写不出两个字",20],["最可恨砀山贼子坐了御座","只有个殿下的猢狲掴他几掴",20],["那讲和的秦桧他不打死蛇","这其间雄赳赳的契丹阿骨打",20],["谁料他本门的骨肉起干戈","四子燕王原不是一把本分手",20],["次后来景清报仇天又不许","只急得张草楦的人皮手干搓",20],["到英宗命该充军道是北狩","也用不着那三声大炮二棒锣",20],["那煤山上的结果那里揣摩","莫不是他强梁的老祖阴骘少",20],["那比斯山巀嶪巑岏皇驻舆","驻舆意不乐海山仙人排云落",21],["恨我迟来不见豪士陈龙友","其人悲歌慷慨能谈兵而使酒",22],["当空一落奇势飞动多横纵","又不见虬髯巍巍直立致天矫",23],["舒长袖似舞兮乃褕袂何曼","奏章而却逢兮愿瞻心之所欢",24]]});
